import csv, collections
vals=list(csv.DictReader(open(VALUES_CSV)))
by=collections.defaultdict(list)
for r in vals:
    if r['value'] in ('','NA','None'): continue
    by[r['timeseries_id']].append((r['timestamp'], float(r['value'])))
for k in by: by[k].sort()

# Core_mid sensor and VAV damper setpoint
core='e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8'  # Zone_F3_Z01 temp sensor
vav ='de92aecc-fc37-5d28-a0b6-fb34b4c34747'  # VAV_F3_Z01 damper setpoint

def month_stats(series, ym):
    vals=[v for ts,v in series if ts.startswith(ym)]
    if not vals: return None
    return (len(vals), sum(vals)/len(vals), min(vals), max(vals))

print("Core_mid sensor monthly (mean C):")
for m in range(1,13):
    ym=f"2018-{m:02d}"
    s=month_stats(by[core], ym)
    if s: print(ym, "n=%d mean=%.2f min=%.2f max=%.2f"%s)
print()
print("VAV_F3_Z01 damper setpoint monthly (mean):")
for m in range(1,13):
    ym=f"2018-{m:02d}"
    s=month_stats(by[vav], ym)
    if s: print(ym, "n=%d mean=%.3f min=%.3f max=%.3f"%s)
